<?php
namespace App\Http\Controllers\Portal;
use App\Http\Controllers\Controller;
use App\Models\{OperationsDataTransfer,OperationsReportSubmission,User};
use App\Services\{OperationsActivationImport,OperationsReporting,PerformanceWorkflow,NotificationService,BrandedSpreadsheet};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Validation\Rule;
class OperationsActivationTransferController extends Controller {
 private function member(Request $r):void {abort_unless(OperationsReporting::member($r->user()),403);}
 private function url(?OperationsDataTransfer $t=null):string {return route('portal.operations.activation-transfers.index',$t?['transfer'=>$t->id]:[]);}
 public function index(Request $r){$this->member($r);$manager=OperationsReporting::manager($r->user());$query=OperationsDataTransfer::query()->when(!$manager,fn($q)=>$q->where('submitted_by',$r->user()->id));$transfers=(clone $query)->latest()->paginate(15)->withQueryString();$transfer=$r->integer('transfer')?(clone $query)->findOrFail($r->integer('transfer')):null;$columns=app(OperationsActivationImport::class)->columns();return response()->view('portal.operations.activation-transfers',compact('transfers','transfer','manager','columns'))->header('Cache-Control','private, no-store');}
 public function template(Request $r){$this->member($r);$columns=app(OperationsActivationImport::class)->columns();return response(app(BrandedSpreadsheet::class)->xlsx([array_values($columns)]))->header('Content-Type','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')->header('Content-Disposition','attachment; filename="activations-import-template.xlsx"')->header('Cache-Control','private, no-store');}
 public function preview(Request $r){$this->member($r);$r->validate(['file'=>'required|file|mimes:xlsx,csv,txt|max:10240','week'=>'required|date_format:Y-m-d','date_format'=>'required|in:d/m/Y,m/d/Y']);$file=$r->file('file');$extension=strtolower($file->getClientOriginalExtension());abort_unless(in_array($extension,['xlsx','csv']),422,'Use .xlsx or .csv.');$fingerprint=hash_file('sha256',$file->getRealPath());$fingerprint=hash('sha256',$fingerprint.$r->week.$r->date_format);$existing=OperationsDataTransfer::where('submitted_by',$r->user()->id)->where('type','import')->where('fingerprint',$fingerprint)->first();if($existing)return redirect($this->url($existing))->with('status','This import already has a preview or submission. Its rows have not been duplicated.');
  $payload=app(OperationsActivationImport::class)->parse($file->getRealPath(),$extension,$r->user(),$r->week,$r->date_format);$payload['filename']=basename($file->getClientOriginalName());$t=OperationsDataTransfer::create(['submitted_by'=>$r->user()->id,'type'=>'import','state'=>'preview','fingerprint'=>$fingerprint,'payload'=>$payload]);PerformanceWorkflow::record('operations_transfer',$t->id,$r->user()->id,'preview',[],['rows'=>count($payload['rows'])],'Activation workbook preview');return redirect($this->url($t));}
 public function submit(Request $r,OperationsDataTransfer $transfer){$this->member($r);abort_unless($transfer->submitted_by===$r->user()->id&&$transfer->type==='import',403);$r->validate(['revision'=>'required|integer','accept_unmapped'=>count($transfer->payload['unmapped']??[])?'accepted':'nullable']);DB::transaction(function()use($r,$transfer){$t=OperationsDataTransfer::lockForUpdate()->findOrFail($transfer->id);if($t->state==='submitted')return;abort_unless($t->state==='preview'&&$t->revision===(int)$r->revision,409,'Import changed. Refresh before submitting.');$ids=[];foreach($t->payload['rows'] as $row){$sourceRow=$row['source_row'];unset($row['source_row']);$row['data']['import_transfer_id']=$t->id;$row['data']['import_row']=$sourceRow;$entry=OperationsReportSubmission::create(['submitted_by'=>$r->user()->id,'kind'=>'activation','state'=>'pending','revision'=>1,'payload'=>$row]);$ids[]=$entry->id;PerformanceWorkflow::record('operations_submission',$entry->id,$r->user()->id,'submit',[],['revision'=>1,'import_transfer_id'=>$t->id],'Imported activation awaiting HOD review');}$p=$t->payload;$p['submission_ids']=$ids;$t->update(['state'=>'submitted','revision'=>$t->revision+1,'payload'=>$p]);});$this->notify($transfer,'Activation import awaiting review');return redirect($this->url($transfer))->with('status','Imported activations submitted. They appear on the dashboard only after HOD approval.');}
 public function requestExport(Request $r){$this->member($r);$columns=app(OperationsActivationImport::class)->columns();$r->validate(['format'=>'required|in:xlsx,pdf','columns'=>'required|array|min:1','columns.*'=>['required','distinct',Rule::in(array_keys($columns))]]);$params=$r->except(['_token','columns','format']);$params['ops_tab']='projects';$queryRequest=$r->duplicate($params,[]);$queryRequest->setMethod('GET');$queryRequest->setUserResolver(fn()=>$r->user());$context=app(OperationsReporting::class)->build($queryRequest);$query=$context['activationExportQuery'];abort_if((clone $query)->count()>2000,422,'Narrow the filters to 2,000 activations or fewer.');$people=User::internalStaff()->pluck('name','id');$rows=$query->orderBy('id')->get()->map(function($row)use($people,$r){$all=['title'=>$row->title,'client'=>$row->client,'project'=>$row->project,'owner'=>$people[$row->owner_id]??'Unassigned','week'=>$row->period_start->toDateString(),'status'=>$row->status]+$row->data;return collect($r->input('columns'))->map(fn($key)=>$all[$key]??'')->all();})->all();abort_unless($rows,422,'No approved activations match these filters.');$t=OperationsDataTransfer::create(['submitted_by'=>$r->user()->id,'type'=>'export','state'=>'pending','format'=>$r->format,'payload'=>['headings'=>collect($r->input('columns'))->map(fn($key)=>$columns[$key])->all(),'rows'=>$rows,'period'=>[$context['from'],$context['to']],'filters'=>$r->except(['_token','columns','format'])]]);PerformanceWorkflow::record('operations_transfer',$t->id,$r->user()->id,'request_export',[],['rows'=>count($rows),'format'=>$r->format],'Activation export requested; frozen snapshot awaits HOD approval');$this->notify($t,'Activation export awaiting approval');return redirect($this->url($t))->with('status','Export requested. The frozen data snapshot must be approved by the HOD before download.');}
 public function review(Request $r,OperationsDataTransfer $transfer){abort_unless(OperationsReporting::manager($r->user())&&$transfer->type==='export',403);$r->validate(['revision'=>'required|integer','decision'=>'required|in:approve,reject','note'=>'required_if:decision,reject|nullable|string|max:2000']);DB::transaction(function()use($r,$transfer){$t=OperationsDataTransfer::lockForUpdate()->findOrFail($transfer->id);abort_unless($t->state==='pending'&&$t->revision===(int)$r->revision,409,'Export request changed. Refresh before reviewing.');$state=$r->decision==='approve'?'approved':'rejected';$t->update(['state'=>$state,'reviewed_by'=>$r->user()->id,'reviewed_at'=>now(),'review_note'=>$r->note,'revision'=>$t->revision+1]);PerformanceWorkflow::record('operations_transfer',$t->id,$r->user()->id,$state,[],['revision'=>$t->revision],'HOD reviewed exact export snapshot');NotificationService::send($t->submitted_by,'Activation export '.$state,'Your activation export request was '.$state.'.',$this->url($t));});return redirect($this->url($transfer))->with('status','Export decision saved.');}
 public function download(Request $r,OperationsDataTransfer $transfer){$this->member($r);abort_unless($transfer->type==='export'&&$transfer->state==='approved'&&($transfer->submitted_by===$r->user()->id||OperationsReporting::manager($r->user())),403);$rows=[$transfer->payload['headings'],...$transfer->payload['rows']];if($transfer->format==='xlsx'){$bytes=app(BrandedSpreadsheet::class)->xlsx($rows);$mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';}else{$pdf=new \Dompdf\Dompdf(['isRemoteEnabled'=>false,'isPhpEnabled'=>false,'isJavascriptEnabled'=>false,'defaultFont'=>'DejaVu Sans']);$pdf->loadHtml(view('portal.operations.activation-export',compact('transfer'))->render());$pdf->setPaper(count($transfer->payload['headings'])>9?'A3':'A4','landscape');$pdf->render();$bytes=$pdf->output();$mime='application/pdf';}PerformanceWorkflow::record('operations_transfer',$transfer->id,$r->user()->id,'download',[],['format'=>$transfer->format],'Approved activation export downloaded');return response($bytes)->header('Content-Type',$mime)->header('Content-Disposition','attachment; filename="approved-activations-'.$transfer->id.'.'.$transfer->format.'"')->header('Cache-Control','private, no-store')->header('X-Content-Type-Options','nosniff');}
 private function notify(OperationsDataTransfer $t,string $title):void {$ids=User::internalStaff()->where('status','active')->get()->filter(fn($u)=>OperationsReporting::manager($u))->pluck('id')->all();NotificationService::sendToMany($ids,$title,'Review request #'.$t->id.'.',$this->url($t));}
}
